func boolToUintptr(b bool) uintptr {
	if b {
		return 1
	}
	return 0
}

func ActiveProgramEXT(program uint32) {
	call.Call1(gpActiveProgramEXT, 0x2, uintptr(program))
}

// set the active program object for a program pipeline object
func ActiveShaderProgram(pipeline uint32, program uint32) {
	call.Call2(gpActiveShaderProgram, 0x22, uintptr(pipeline), uintptr(program))
}

func ActiveShaderProgramEXT(pipeline uint32, program uint32) {
	call.Call2(gpActiveShaderProgramEXT, 0x22, uintptr(pipeline), uintptr(program))
}

// select active texture unit
func ActiveTexture(texture uint32) {
	call.Call1(gpActiveTexture, 0x2, uintptr(texture))
}

func AlphaFuncQCOM(xfunc uint32, ref float32) {
	call.Call2(gpAlphaFuncQCOM, 0x62, uintptr(xfunc), uintptr(math.Float32bits(ref)))
}

func ApplyFramebufferAttachmentCMAAINTEL() {
	call.Call0(gpApplyFramebufferAttachmentCMAAINTEL, 0x0)
}

// Attaches a shader object to a program object
func AttachShader(program uint32, shader uint32) {
	call.Call2(gpAttachShader, 0x22, uintptr(program), uintptr(shader))
}

func BeginConditionalRenderNV(id uint32, mode uint32) {
	call.Call2(gpBeginConditionalRenderNV, 0x22, uintptr(id), uintptr(mode))
}

func BeginPerfMonitorAMD(monitor uint32) {
	call.Call1(gpBeginPerfMonitorAMD, 0x2, uintptr(monitor))
}

func BeginPerfQueryINTEL(queryHandle uint32) {
	call.Call1(gpBeginPerfQueryINTEL, 0x2, uintptr(queryHandle))
}

// delimit the boundaries of a query object
func BeginQuery(target uint32, id uint32) {
	call.Call2(gpBeginQuery, 0x22, uintptr(target), uintptr(id))
}

func BeginQueryEXT(target uint32, id uint32) {
	call.Call2(gpBeginQueryEXT, 0x22, uintptr(target), uintptr(id))
}

// start transform feedback operation
func BeginTransformFeedback(primitiveMode uint32) {
	call.Call1(gpBeginTransformFeedback, 0x2, uintptr(primitiveMode))
}

// Associates a generic vertex attribute index with a named attribute variable
func BindAttribLocation(program uint32, index uint32, name *uint8) {
	call.Call3(gpBindAttribLocation, 0x422, uintptr(program), uintptr(index), uintptr(unsafe.Pointer(name)))
}

// bind a named buffer object
func BindBuffer(target uint32, buffer uint32) {
	call.Call2(gpBindBuffer, 0x22, uintptr(target), uintptr(buffer))
}

